#include "document.h"
#include "selection_pattern_brush.h"
#include <iostream>
#define CHECK(x) do{if(!(x))throw std::runtime_error(#x);}while(false)
int main(){try{using namespace moon;Document d(4,2);d.beginStroke({1,0},0x80332211);d.commitStroke();d.beginStroke({2,0},0xff665544);d.commitStroke();auto before=d.historySize();auto captured=createSelectionPatternBrush(d.pixels(),4,2,SelectionMask{1,0,2,2,{1,0,1,1}});CHECK(captured&&captured->sourceX==1&&captured->sourceY==0&&captured->colors==std::vector<std::uint32_t>({0x80332211,0,0,0}));CHECK(captured->selectionColorMapping);CHECK(!PatternBrush{}.selectionColorMapping);CHECK(d.historySize()==before);auto original=captured->colors;remapSelectionPatternBrush(captured,0xff112233,0x80665544);CHECK(captured->colors==original);CHECK(captured->paintColors==std::vector<std::uint32_t>({0x40665544,0,0,0}));auto ordinary=captured;ordinary->selectionColorMapping=false;ordinary->paintColors.clear();remapSelectionPatternBrush(ordinary,0,0);CHECK(ordinary->paintColors.empty());CHECK(!createSelectionPatternBrush(d.pixels(),4,2,SelectionMask{0,1,4,1,{}}));bool large=false;try{createSelectionPatternBrush(std::vector<std::uint32_t>(65),65,1,SelectionMask{0,0,65,1,{}});}catch(const std::invalid_argument&){large=true;}CHECK(large);// brushes.ts reads the first duplicate palette ID and leaves sparse exterior transparent.
PaletteState palette;palette.entries={{0,U"Zero",0xff010203},{7,U"First",0x80332211},{7,U"Last",0xffaabbcc},{9,U"Transparent",0x00123456}};
RasterColorContext colors(palette.entries,palette.order());timeline::Surface source;source.width=3;source.height=1;source.offsetX=1;source.format=timeline::RasterFormat::Indexed;source.pixels={0,7,9};const auto originalPixels=source.pixels;
auto indexed=createSelectionPatternBrush(source,5,1,SelectionMask{0,0,5,1,{}},&colors);
CHECK(indexed);CHECK(indexed->colors==std::vector<std::uint32_t>({0,0xff010203,0x80332211,0x00123456,0}));CHECK(indexed->coverage==std::vector<std::uint8_t>({0,255,128,0,0}));
auto masked=createSelectionPatternBrush(&source,5,1,SelectionMask{-1,0,5,1,{1,1,0,1,1}},&colors);CHECK(masked&&masked->sourceX==0&&masked->width==4);CHECK(masked->colors==std::vector<std::uint32_t>({0,0,0x80332211,0x00123456}));
CHECK(!createSelectionPatternBrush(&source,5,1,SelectionMask{3,0,2,1,{}},&colors));CHECK(!createSelectionPatternBrush(static_cast<const timeline::Surface*>(nullptr),5,1,SelectionMask{0,0,5,1,{}},&colors));CHECK(source.pixels==originalPixels);CHECK(d.historySize()==before);
std::cout<<"selection pattern brush passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
